
struct Counting{inner:sha3::Shake256Reader,bytes:usize}impl XofReader for Counting{fn read(&mut self,out:&mut[u8]){self.bytes+=out.len();XofReader::read(&mut self.inner,out)}}
fn paired(ops:&[Op],nq:usize,nb:usize,q:Vec<u64>,b:Vec<u64>,readers:Vec<sha3::Shake256Reader>,tag:&str){let p=Compact::compile(ops);assert_eq!(std::mem::size_of::<CompactOp>(),16);let mut rng=vec![0u64;p.rng_count*8];for j in 0..8{let mut bytes=vec![0;p.rng_count*8];XofReader::read(&mut readers[j].clone(),&mut bytes);for i in 0..p.rng_count{rng[i*8+j]=u64::from_le_bytes(bytes[i*8..i*8+8].try_into().unwrap());}}let mut actualq=q.clone();let mut actualb=b.clone();let mut phase=[0u64;8];let mut stack=vec![0u64;4096*8];let mut used=0;let start=std::time::Instant::now();assert_eq!(unsafe{(exact_backend().run)(p.ops.as_ptr(),p.ops.len(),actualq.as_mut_ptr(),actualb.as_mut_ptr(),phase.as_mut_ptr(),rng.as_ptr(),p.rng_count,stack.as_mut_ptr(),4096,&mut used)},0);assert_eq!(used,p.rng_count);let kernel=start.elapsed().as_secs_f64();for j in 0..8{let mut reader=Counting{inner:readers[j].clone(),bytes:0};let mut sim=Simulator::new(nq,nb,&mut reader);for i in 0..nq{sim.qubits[i]=q[i*8+j];}for i in 0..nb{sim.bits[i]=b[i*8+j];}sim.apply_iter(ops.iter());for i in 0..nq{assert_eq!(sim.qubits[i],actualq[i*8+j],"{tag} q{i} instance{j}");}for i in 0..nb{assert_eq!(sim.bits[i],actualb[i*8+j],"{tag} bit{i} instance{j}");}assert_eq!(sim.phase,phase[j],"{tag} phase instance{j}");drop(sim);assert_eq!(reader.bytes,p.rng_count*8);}println!("WIDE_PAIRED_PASS tag={tag} batches=8 shots=512 qubits={nq} bits={nb} compact_bytes=16 rng_words={} kernel_seconds={kernel:.6} full_qubit_bit_phase_rng_equality=true",p.rng_count);}
fn reader(n:u64)->sha3::Shake256Reader{let mut h=Shake256::default();h.update(b"wide-compact-fixture-v1");h.update(&n.to_le_bytes());h.finalize_xof()}
fn fixture(){use OperationType::*;let z=u64::MAX;let op=|k,t,bt,c|Op{kind:k,q_control1:QubitId(z),q_control2:QubitId(z),q_target:QubitId(t),c_target:BitId(bt),c_condition:BitId(c),r_target:RegisterId(z)};let ops=vec![op(BitStore1,z,65535,z),op(X,0,z,65535),op(BitStore0,z,65535,z),op(X,0,z,65535),op(BitStore1,z,70000,z),op(PushCondition,z,z,70000),op(BitInvert,z,70000,z),op(X,1,z,z),op(Hmr,1,70001,z),op(PopCondition,z,z,z),op(Z,0,z,70001),op(R,0,z,z),op(Hmr,1,65535,70001)];for o in &ops{o.validate();}let mut q=vec![0;2*8];let mut b=vec![0;70002*8];for j in 0..8{q[j]=0x9e3779b97f4a7c15u64.wrapping_mul(j as u64+1);q[8+j]=!q[j];b[70001*8+j]=!q[j];}paired(&ops,2,70002,q,b,(0..8).map(reader).collect(),"high_classical_ids_65535_70000_nested_snapshot");}
fn main(){assert!(std::is_x86_feature_detected!("avx512f"));fixture();let a:Vec<_>=std::env::args().collect();let ops=load_ops(&a[1]).unwrap();let(nq,nb,_,regs)=analyze_ops(ops.iter());let n=ops.len();assert!(n>96);let mut h=Shake256::default();h.update(b"quantum_ecc-fiat-shamir-v2");h.update(&(n as u64).to_le_bytes());for op in &ops[..n-96]{h.update(&record49(op));}let curve=FastCurveC::new(16);let mut q=vec![0;nq as usize*8];let mut b=vec![0;nb as usize*8];let mut readers=Vec::new();for j in 0..8{let mut tail=ops[n-96..].to_vec();for(k,pair)in tail.chunks_exact_mut(2).enumerate(){assert_eq!(pair[0],pair[1]);assert_eq!(pair[0].kind,OperationType::X);assert_eq!(pair[0].c_condition.0,u64::MAX);for o in pair{o.q_target=QubitId((j as u64>>k)&1);}}let mut hj=h.clone();for o in tail{hj.update(&record49(&o));}let mut r=hj.finalize_xof();let mut keys=vec![0;NUM_TESTS*64];XofReader::read(&mut r,&mut keys);let mut scalars=Vec::new();for row in keys[..64*64].chunks_exact(64){scalars.push(U256::from_le_slice(&row[..32]));scalars.push(U256::from_le_slice(&row[32..]));}let points=curve.points_with_sums(&scalars);let mut dummy=reader(0);let mut initial=Simulator::new(nq as usize,nb as usize,&mut dummy);for(lane,(t,o,_))in points.iter().enumerate(){assert!(t.0!=o.0&&!(t.0.is_zero()&&t.1.is_zero())&&!(o.0.is_zero()&&o.1.is_zero()));for(reg,value)in regs[..4].iter().zip([t.0,t.1,o.0,o.1]){initial.set_register(reg,value,lane);}}for i in 0..nq as usize{q[i*8+j]=initial.qubits[i];}for i in 0..nb as usize{b[i*8+j]=initial.bits[i];}readers.push(r);}paired(&ops,nq as usize,nb as usize,q,b,readers,"frozen_full_stream_actual_fiat_first_batches");}
